};

types.pspGp:
static inline u32 pspGetGp(void) {
    u32 gp;
    asm volatile("move %0, $gp" : "=r"(gp));
    return gp;
}
static inline u32 pspSetGp(u32 gp) {
    u32 old;
    asm volatile("move %0, $gp\n\tmove $gp, %1" : "=&r"(old) : "r"(gp) : "memory");
    return old;
}
